function MiniChart({values,labels}:{values:number[];labels:string[]}) {
  const max=Math.max(...values,1);
  const points=values.map((v,i)=>`${(i/(Math.max(values.length-1,1)))*100},${92-(v/max)*78}`).join(" ");
  return <div className="sa-chart-wrap"><div className="sa-chart-y"><span>{max}</span><span>{Math.round(max*.66)}</span><span>{Math.round(max*.33)}</span><span>0</span></div><div className="sa-chart"><div className="sa-chart-grid"><i/><i/><i/><i/></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="sa-chart-svg" aria-label="Recent activity chart"><defs><linearGradient id="sa-chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#4e9bff" stopOpacity=".3"/><stop offset="100%" stopColor="#4e9bff" stopOpacity="0"/></linearGradient></defs><polygon points={`0,100 ${points} 100,100`} fill="url(#sa-chart-fill)"/><polyline points={points} fill="none" stroke="#398dff" strokeWidth="1.7" vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round"/></svg><div className="sa-chart-labels">{labels.map(l=><span key={l}>{l}</span>)}</div></div></div>;
}

