  async function handleCacheAction(action:string){
    if(action==="storage") { setApplicationSettingsTab("storage"); setUtilitySettingsNotice(""); return; }
    let removed=0;
    try {
      if ("caches" in window) {
        const keys=await window.caches.keys();
        const targets=action==="view"?keys.filter(k=>/view|image|asset|vite/i.test(k)):keys;
        const results=await Promise.all(targets.map(k=>window.caches.delete(k)));
        removed=results.filter(Boolean).length;
      }
      if(action==="application") { try { sessionStorage.clear(); } catch {} }
      const labels:Record<string,string>={view:"Clear View Cache",route:"Clear Route Cache",config:"Clear Config Cache",application:"Application Clear Cache"};
      setUtilitySettingsNotice(`${labels[action]||"Cache action"}: cleared ${removed} browser cache ${removed===1?"entry":"entries"}. Server-side caches require a backend cache endpoint.`);
    } catch {
      setUtilitySettingsNotice("Unable to clear browser cache automatically. Please clear your browser cache manually.");
    }
  }


