   const limit=(value:string,mode:string)=>mode==="unlimited"?null:Math.max(0,Number(value||0));
   const body={name:planForm.name.trim(),code:(editingPlan?.code||planForm.name.trim().toUpperCase().replace(/[^A-Z0-9]+/g,"_").replace(/^_|_$/g,"")),chatPrefix:planForm.chatPrefix.trim(),description:planForm.description.trim(),sortOrder:Math.max(0,Number(planForm.sortOrder||0)),price,currency:planForm.currency.toUpperCase(),billingInterval:interval,monthlyPrice:monthly,yearlyPrice:yearly,customerLimit:limit(planForm.customerLimit,planForm.customerLimitMode),productLimit:limit(planForm.productLimit,planForm.productLimitMode),subscriptionLimit:limit(planForm.subscriptionLimit,planForm.subscriptionLimitMode),icon:planForm.icon,isActive:planForm.isActive,isPopular:planForm.isPopular,isTrial:planForm.isTrial,features:planForm.features.split("\n").map(v=>v.trim()).filter(Boolean),extraHomes:Math.max(0,Number(planForm.extraHomes||0)),playerVaults:planForm.playerVaults,dailyKit:planForm.dailyKit.trim(),utilCommands:planForm.utilCommands,flight:planForm.flight,coloredChat:planForm.coloredChat,joinMessage:planForm.joinMessage,category:"rank"};
   setSavingPlan(true);try{await api(editingPlan?`/admin/plans/${editingPlan._id}`:"/admin/plans",{method:editingPlan?"PUT":"POST",body:JSON.stringify(body)});setPlanModal(false);setError("");await load();}catch(e){setError(e instanceof Error?e.message:"Could not save plan");}finally{setSavingPlan(false);}
