 async function saveFeature(e:React.FormEvent){
   e.preventDefault();setSavingFeature(true);setError("");
   const featureName=featureForm.featureName.trim();
   const featureKey=(featureForm.featureKey.trim()||featureName.toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_|_$/g,""));
   let value:any=featureForm.valueText;
   if(featureForm.valueType==="boolean") value=featureForm.valueText==="true";
   if(featureForm.valueType==="number"){value=Number(featureForm.valueText);if(!Number.isFinite(value)){setError("Enter a valid numeric feature value.");setSavingFeature(false);return;}}
   if(!featureForm.planCode||!featureName||!featureKey){setError("Rank, feature name, and feature key are required.");setSavingFeature(false);return;}
   try{
     const body={planCode:featureForm.planCode,featureName,featureKey,value,valueType:featureForm.valueType,enabled:featureForm.enabled};
     await api(editingFeature?`/admin/features/${editingFeature._id}`:"/admin/features",{method:editingFeature?"PUT":"POST",body:JSON.stringify(body)});
     setFeatureModal(false);await load();
   }catch(e){setError(e instanceof Error?e.message:"Could not save feature");}finally{setSavingFeature(false);}
 }
