 const filteredUsers=users.filter(u=>`${u.username} ${u.email} ${u.role} ${(u as any).country||""}`.toLowerCase().includes(userQuery.trim().toLowerCase())).sort((a,b)=>{const da=a.createdAt?new Date(a.createdAt).getTime():0;const db=b.createdAt?new Date(b.createdAt).getTime():0;return userSortOrder==="desc"?db-da:da-db;});
 const stats=[
  {label:"Total Users",value:overview?.users??"—",icon:Users,tone:"blue",note:"Registered accounts"},
  {label:"Total Customers",value:overview?.customers??"—",icon:UserRound,tone:"violet",note:"Customer records"},
  {label:"Subscriptions",value:overview?.subscriptions??"—",icon:CalendarDays,tone:"green",note:"All subscription records"},
  {label:"Monthly Recurring Revenue",value:overview?new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:2}).format(overview.monthlyRecurringRevenue??0):"—",icon:BadgeDollarSign,tone:"amber",note:`${overview?.activeSubscriptions??0} active subscriptions`},
 ];
 const totalRankValue=plans.filter(p=>p.isActive).length;
 const recentDays=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));d.setHours(0,0,0,0);return d;});
 const countByDay=(items:any[],field="createdAt")=>recentDays.map(day=>items.filter(item=>{const value=item?.[field];if(!value)return false;const date=new Date(value);return date.toDateString()===day.toDateString();}).length);
 const dayLabels=recentDays.map(d=>d.toLocaleDateString("en-US",{weekday:"short"}));
 const subscriptionTrend=countByDay(subs);
 const storeTrend=countByDay(payments).map((n,i)=>n+countByDay(customers)[i]+countByDay(plans)[i]);
 const filteredOrderPayments=payments.filter(p=>orderFilter==="all"||(orderFilter==="cancelled"?p.status==="failed":orderFilter==="bank_pending"?(p.status==="pending"&&p.provider==="manual"):p.status===orderFilter));
 const orderPageCount=Math.max(1,Math.ceil(filteredOrderPayments.length/ordersPerPage));
 const sortedOrderPayments=[...filteredOrderPayments].sort((a,b)=>{const aId=String(a.orderId??a.order_id??a.orderNumber??a._id??"");const bId=String(b.orderId??b.order_id??b.orderNumber??b._id??"");return orderIdSort==="asc"?aId.localeCompare(bId,undefined,{numeric:true}):bId.localeCompare(aId,undefined,{numeric:true});});
 const visibleOrderPayments=sortedOrderPayments.slice((currentOrderPage-1)*ordersPerPage,currentOrderPage*ordersPerPage);
 function printSelectedOrders(){
  const chosen=payments.filter(p=>selectedOrderIds.includes(String(p._id)));
  if(!chosen.length){setError("Select one or more orders using the checkboxes before printing.");return;}
  const escapeHtml=(value:unknown)=>String(value??"—").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]!));
  const money=(p:any)=>escapeHtml((p.currency==="USD"||!p.currency?"$":`${p.currency} `)+Number(p.amount||0).toFixed(2));
  const invoicePages=chosen.map((p,index)=>{
   const id=p.orderId??p.order_id??p.orderNumber??p._id;
   const date=p.createdAt?new Date(p.createdAt).toLocaleDateString("en-GB"):"—";
   const userName=p.user?.username||p.customer?.name||"—";
   const userEmail=p.user?.email||p.customer?.email||"—";
   const packageName=p.plan?.name||p.planName||p.packageName||p.package?.name||p.package||p.tier?.name||p.description||"—";
   const gateway=p.provider==="manual"?"Cash":p.provider||p.gateway||"—";
   const status=p.status==="succeeded"?"Paid":p.status==="failed"?"Cancelled":p.status==="pending"&&p.provider==="manual"?"Bank Pending":p.status||"Pending";
   const subtotal=Number(p.amount||0);
   return `<section class="invoice ${index?"new-page":""}">
    <h1>Invoice #${escapeHtml(id)}</h1>
    <div class="info-grid">
     <div class="info"><strong>Invoice</strong><span>Invoice #${escapeHtml(id)}</span></div>
     <div class="info"><strong>Order ID</strong><span>${escapeHtml(id)}</span></div>
     <div class="info"><strong>Date Added</strong><span>${escapeHtml(date)}</span></div>
     <div class="info"><strong>Store</strong><span>StrafeMC</span></div>
     <div class="info"><strong>Customer</strong><span>${escapeHtml(userName)}</span></div>
     <div class="info"><strong>Customer E-Mail</strong><span>${escapeHtml(userEmail)}</span></div>
     <div class="info"><strong>Payment Method</strong><span>${escapeHtml(gateway)}</span></div>
     <div class="info"><strong>Order Status</strong><span>${escapeHtml(status)}</span></div>
    </div>
    <div class="address"><strong>Customer / Billing Details</strong><br>${escapeHtml(userName)}<br>${escapeHtml(userEmail)}</div>
    <table><thead><tr><th>Product / Package</th><th>Model</th><th class="number">Quantity</th><th class="number">Unit Price</th><th class="number">Total</th></tr></thead>
    <tbody><tr><td>${escapeHtml(packageName)}</td><td>${escapeHtml(p.plan?.code||p.planCode||"—")}</td><td class="number">1</td><td class="number">${money(p)}</td><td class="number">${money(p)}</td></tr>
    <tr><td colspan="4" class="summary-label">Sub-Total</td><td class="number">${money(p)}</td></tr>
    <tr><td colspan="4" class="summary-label">Total</td><td class="number">${money(p)}</td></tr></tbody></table>
   </section>`;
  }).join("");
  const popup=window.open("","_blank","width=1100,height=750");
  if(!popup){setError("The print window was blocked. Allow pop-ups and try again.");return;}
  popup.document.write(`<!doctype html><html><head><title>Selected Order Invoices</title><meta charset="utf-8"><style>
  *{box-sizing:border-box}body{font:14px Arial,Helvetica,sans-serif;color:#30343b;margin:0;padding:28px;background:#fff}.invoice{max-width:1120px;margin:0 auto 36px}.invoice.new-page{break-before:page;page-break-before:always}h1{font-size:28px;font-weight:400;color:#555;margin:0 0 8px}.info-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 20px;margin-bottom:14px}.info{min-height:54px;border:1px solid #dce2e8;padding:8px}.info strong,.info span{display:block;font-weight:400;line-height:1.45}.info span{color:#454b53}.address{border:1px solid #dce2e8;padding:10px;margin:0 0 14px;line-height:1.5}.address strong{font-weight:400}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #dce2e8;padding:9px 8px;text-align:left}th{font-weight:700;background:#fff;color:#111}td.number,th.number{text-align:right}.summary-label{text-align:right;font-weight:700} @page{size:A4 landscape;margin:12mm}@media print{body{padding:0}.invoice{max-width:none;margin:0}.invoice:not(:last-child){break-after:page;page-break-after:always}.invoice.new-page{break-before:page;page-break-before:always}tr,.info,.address{break-inside:avoid}}@media(max-width:700px){.info-grid{grid-template-columns:repeat(2,minmax(0,1fr))}body{padding:12px}}
  </style></head><body>${invoicePages}<script>window.onload=()=>{window.focus();window.print();};<\/script></body></html>`);
  popup.document.close();
 }
